// --- Basic mlock() ---
#define DATA_SIZE 65536
void* sensitive_data = malloc(DATA_SIZE);

// Lock memory range into physical RAM
int status = mlock(sensitive_data, DATA_SIZE);

if (status == 0) {
    // Memory is guaranteed resident
}

// Unlock when finished
munlock(sensitive_data, DATA_SIZE);
free(sensitive_data);

// --- mlock2() with Flags ---
#define PAGE_SZ 4096
#define FLAGS MLOCK_ONFAULT

void* lazy_lock_mem = mmap(NULL, PAGE_SZ, PROT_READ|PROT_WRITE, MAP_ANON|MAP_PRIVATE, -1, 0);

// Lock pages, but defer residency until first access/fault
mlock2(lazy_lock_mem, PAGE_SZ, FLAGS);

// Accessing the page makes it resident
*(char*)lazy_lock_mem = 1;
